                    print(f"  {k}: {masked}")
        else:
            print(f"Result: {json.dumps(r)[:600]}")
except urllib.error.HTTPError as e:
    print(f'HTTP {e.code}: {e.read().decode("utf-8")[:400]}')
PYEOF

